export type Expense = {
  id: string
  label: string
  amount: number
  currency: string
  status: string
}

export type NewExpense = Pick<Expense, 'label' | 'amount' | 'currency'>

export type FieldErrors = Partial<Record<keyof NewExpense, string>>

export class ExpenseValidationError extends Error {
  readonly errors: Record<string, string>

  constructor(errors: Record<string, string>) {
    super('Invalid expense')
    this.errors = errors
  }
}

export type ExpenseGateway = {
  list: () => Promise<Expense[]>
  create: (expense: NewExpense) => Promise<Expense>
}

export const listExpenses = (gateway: ExpenseGateway) => gateway.list()

export type SubmitResult = { expense: Expense } | { errors: Record<string, string> }

export const submitExpense = async (gateway: ExpenseGateway, expense: NewExpense): Promise<SubmitResult> => {
  try {
    return { expense: await gateway.create(expense) }
  } catch (error) {
    if (error instanceof ExpenseValidationError) return { errors: error.errors }
    throw error
  }
}
