import { ExpenseValidationError } from '../application/expenses'
import type { Expense, ExpenseGateway } from '../application/expenses'

const URL = '/api/expenses'

export const httpExpenseGateway: ExpenseGateway = {
  async list() {
    const response = await fetch(URL, { headers: { Accept: 'application/json' } })
    if (!response.ok) throw new Error(`Could not load expenses (${response.status})`)
    return (await response.json()) as Expense[]
  },

  async create(expense) {
    const response = await fetch(URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify(expense),
    })
    if (response.status === 422) {
      const body = (await response.json()) as { errors?: Record<string, string> }
      throw new ExpenseValidationError(body.errors ?? {})
    }
    if (!response.ok) throw new Error(`Could not submit the expense (${response.status})`)
    return (await response.json()) as Expense
  },
}
