import { useCallback, useEffect, useState } from 'react'

import { listExpenses, submitExpense } from '../../application/expenses'
import type { Expense, ExpenseGateway, NewExpense } from '../../application/expenses'

export const useExpenses = (gateway: ExpenseGateway) => {
  const [expenses, setExpenses] = useState<Expense[]>([])
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState<string | null>(null)

  useEffect(() => {
    let active = true
    listExpenses(gateway)
      .then((items) => {
        if (active) setExpenses(items)
      })
      .catch((error: unknown) => {
        if (active) setLoadError(error instanceof Error ? error.message : 'Could not load expenses')
      })
      .finally(() => {
        if (active) setLoading(false)
      })
    return () => {
      active = false
    }
  }, [gateway])

  const submit = useCallback(
    async (expense: NewExpense): Promise<Record<string, string>> => {
      const result = await submitExpense(gateway, expense)
      if ('errors' in result) return result.errors
      setExpenses((current) => [...current, result.expense])
      return {}
    },
    [gateway],
  )

  return { expenses, loading, loadError, submit }
}
